// Package entities holds the go-gardening-demo's shared entity types —
// the JSON shapes generated by gendata into go-gardening-demo/initial-data
// and consumed by every gardening-demo MCP server and the CLI under
// go-gardening-demo/servers and go-gardening-demo/cli. It exists as its
// own importable (non-main) package specifically so those consumers can
// share these definitions with gendata (itself package main, and so not
// importable by anything else — see this repo's own documented "package
// main can't cross-import another package main" constraint).
package entities

// Product is the canonical gardening-equipment catalog item — the shared
// identity behind one or more ProductSupply rows (different suppliers of
// the same product). Not itself written to a JSON file: it exists only to
// keep the 30 canonical id/name pairs in one place for every entity that
// references a product by id.
type Product struct {
	ID   string
	Name string
}

// ProductSupply is one supplier's offer for a Product — up to 3 per
// Product (see gendata/staticdata.go's productSuppliers). CostToUserPerRetailUnit
// is deliberately identical across every ProductSupply row for the same
// ProductID: the catalog price doesn't change depending on which supplier
// happens to be fulfilling it.
type ProductSupply struct {
	ID                      string  `json:"id"`
	ProductID               string  `json:"productId"`
	Name                    string  `json:"name"`
	SupplierName            string  `json:"supplierName"`
	UnitsPerWholesaleUnit   int     `json:"unitsPerWholesaleUnit"`
	CostPerWholesaleUnit    float64 `json:"costPerWholesaleUnit"`
	CostToUserPerRetailUnit float64 `json:"costToUserPerRetailUnit"`
}

// SupplyOrder is a restock order placed against one ProductSupply line.
// All 100 in the seed data are fulfilled (the spec's "10% not yet
// fulfilled" note applies only to OnlineCustomerOrder), but
// FulfillmentActualDate is nullable (like OnlineCustomerOrder's) because a
// live server (garden-online-store) can create new, not-yet-fulfilled
// supply orders via add_supply_order.
type SupplyOrder struct {
	ID                    string  `json:"id"`
	ProductSupplyID       string  `json:"productSupplyId"`
	OrderDate             string  `json:"orderDate"`
	FulfillmentTargetDate string  `json:"fulfillmentTargetDate"`
	FulfillmentActualDate *string `json:"fulfillmentActualDate"`
	NumberOfOrderedUnits  int     `json:"numberOfOrderedUnits"`
	TotalCost             float64 `json:"totalCost"`
}

// CustomerType is a lookup entity: OnlineCustomer.Type references one of
// these by id.
type CustomerType struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

// CustomerSentiment is a lookup entity: OnlineCustomer.Sentiment
// references one of these by id.
type CustomerSentiment struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

// ContactDetails is the {name, address, phone} shape shared by
// OnlineCustomer and Staffer.
type ContactDetails struct {
	Name    string `json:"name"`
	Address string `json:"address"`
	Phone   string `json:"phone"`
}

// OnlineCustomer is a store customer.
type OnlineCustomer struct {
	ID        string         `json:"id"`
	Details   ContactDetails `json:"details"`
	Type      string         `json:"type"`      // CustomerType id
	Sentiment string         `json:"sentiment"` // CustomerSentiment id
}

// OnlineCustomerOrder is a retail order placed by an OnlineCustomer for a
// Product. DealID is set (omitted otherwise) when the order's price
// reflects an active Deal — see gendata/build.go's buildOnlineCustomerOrders'
// discount logic. About 10% of the seed data's 500 orders (the most
// recently placed ones) have no FulfillmentActualDate yet.
type OnlineCustomerOrder struct {
	ID                    string  `json:"id"`
	CustomerID            string  `json:"customerId"`
	ProductID             string  `json:"productId"`
	OrderDate             string  `json:"orderDate"`
	FulfillmentTargetDate string  `json:"fulfillmentTargetDate"`
	FulfillmentActualDate *string `json:"fulfillmentActualDate"`
	NumberOfRetailUnits   int     `json:"numberOfRetailUnits"`
	TotalPrice            float64 `json:"totalPrice"`
	DealID                *string `json:"dealId,omitempty"`
}

// StaffRole is one of the fixed role names (see gendata/staticdata.go's
// staffRoles). Staffer.Roles references these by id.
type StaffRole struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

// Staffer is a store employee, who may hold more than one StaffRole.
type Staffer struct {
	ID      string         `json:"id"`
	Details ContactDetails `json:"details"`
	Roles   []string       `json:"roles"` // StaffRole ids
}

// CustomerServiceCall is a support interaction.
type CustomerServiceCall struct {
	ID                   string  `json:"id"`
	CustomerID           string  `json:"customerId"`
	HandledByStafferID   string  `json:"handledByStafferId"`
	CallDate             string  `json:"callDate"`
	IssueText            string  `json:"issueText"`
	ResolutionDate       *string `json:"resolutionDate"`
	EscalatedToManager   bool    `json:"escalatedToManager"`
	EscalatedToStafferID *string `json:"escalatedToStafferId,omitempty"`
}

// Deal is a discount scoped to specific ProductSupply rows - IDs holds
// ProductSupply.ID values (e.g. "ps-022"), not Product/ProductSupply.ProductID
// values, so a deal can single out one supplier's row rather than
// automatically covering every supplier of a product.
//
// DiscountPercentages is keyed by CustomerType id (see
// gendata/staticdata.go's customerTypeOneTime/Returning/VIP, or a live
// deployment's own customer_types.json): a customer type absent from the
// map isn't eligible for this deal at all - that's how a deal can be
// scoped to only one type (e.g. a VIP-only loyalty program, see
// gendata/staticdata.go's dealDefs).
//
// StartDate/EndDate are nil for a deal with no bound on that side - e.g.
// an always-in-effect program has both nil. Non-nil values are YYYY-MM-DD.
type Deal struct {
	ID                  string             `json:"id"`
	Name                string             `json:"name"`
	StartDate           *string            `json:"startDate,omitempty"`
	EndDate             *string            `json:"endDate,omitempty"`
	IDs                 []string           `json:"ids"`
	DiscountPercentages map[string]float64 `json:"discountPercentages"`
}

// DiscountFor returns the discount percentage this deal offers
// customerType, or ok=false if that customer type isn't covered by this
// deal at all.
func (d Deal) DiscountFor(customerType string) (percentage float64, ok bool) {
	percentage, ok = d.DiscountPercentages[customerType]
	return percentage, ok
}
